def slug(s): return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',str(s).lower())).strip('-')
def esc(s): return html.escape(str(s or ''),quote=True)
def is_github(t): return bool(re.search(r'github\.com|github\.io',f"{t.get('url','')} {t.get('source','')} {t.get('repository','')} {t.get('github','')}",re.I))
def logo(t):
    if is_github(t): return 'https://github.githubassets.com/favicons/favicon.svg'
    return t.get('logo') or 'https://www.google.com/s2/favicons?domain='+__import__('urllib.parse').parse.quote(__import__('urllib.parse').urlparse(t.get('url','')).hostname or '')+'&sz=128'
def cat_info(t):
    cat=t.get('category') or 'AI Tool'; return BEST.get(cat,'Explore AI-assisted workflows, automate parts of your work and create useful first drafts faster.'),LIMITS.get(cat,'AI output can be inaccurate or incomplete. Features, privacy terms and usage limits can change, so verify important results on the provider website.')
def related_tools(current,tools):
    cat=current.get('category'); c=[t for t in tools if t is not current and (t.get('category')==cat or not cat)]; return (c if len(c)>=3 else [t for t in tools if t is not current])[:3]
